    /// # Description
    ///
    /// Checks if the page size flag is set (large page).
    ///
    /// # Returns
    ///
    /// `true` if the page size flag is set, `false` otherwise.
    ///
    #[inline(always)]
    pub fn is_large_page(&self) -> bool { ... }

