    /// # Description
    ///
    /// Sets page size.
    ///
    /// # Parameters
    ///
    /// - `page_size`: The page size flag.
    ///
    #[inline(always)]
    pub fn set_page_size(&mut self, page_size: PageSizeFlag) { ... }

    ///
    /// # Description
    ///
    /// Constructs a [`PageDirectoryEntryFlags`] from a raw value.
    ///
    /// # Parameters
    ///
    /// - `value`: The raw value.
    ///
    /// # Returns
    ///
    /// A [`PageDirectoryEntryFlags`].
